class Timer:
    def __init__(self, duration):
        self.duration = duration
        self.remaining = duration

    def tick(self, seconds=1):
        if seconds >= 0:
            self.remaining = max(0, self.remaining - seconds)
        return self.remaining

    def reset(self):
        self.remaining = self.duration

timer = Timer(5)
print(timer.tick(2))
